def _rec(id_: str, category: str, family: str, title: str, summary: str, tags: str, **extra: Any) -> Record:
    return {"id": id_, "category": category, "family": family, "title": title, "summary": summary, "tags": tags.split(), **extra}


def _env(package: str) -> dict[str, Any] | None:
    size = PACKAGES.get(package)
    return {"shape": "box", "x": size[0], "y": size[1], "z": size[2]} if size else None


